
--Q1. What is the total revenue generated by male vs. female customers?
SELECT 
	gender,
	SUM(purchase_amount) AS revenue
FROM customer_data
GROUP BY gender;

--Q2. Which customers used a discount but still spent more than the average purchase amount?
SELECT 
	customer_id,
	purchase_amount
FROM customer_data
WHERE discount_applied ='Yes' 
	AND purchase_amount>(SELECT AVG(purchase_amount) FROM customer_data);

--Q3. Which are the top 5 products with the highest average review rating?
SELECT TOP 5
	item_purchased,
	CAST(avg(review_rating) AS DECIMAL(5,2)) AS avg_review_rating
FROM customer_data
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC;

--Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
SELECT shipping_type,
	AVG(purchase_amount) AS avg_purchase_amount
FROM customer_data
WHERE shipping_type in ('Standard','Express')
GROUP BY shipping_type

--Q5. Do subscribed customers spend more? Compare average spend and total revenue
--    between subscribers and non-subscribers?
SELECT 
	subscription_status,
	COUNT(customer_id) AS total_customers,
	AVG(purchase_amount) AS avg_spend,
	SUM(purchase_amount) AS total_revenue
FROM customer_data
GROUP BY subscription_status;

--Q6. Which 5 products have the highest percentage of purchases with discounts applied?
SELECT TOP 5
    item_purchased,
    CAST(
        COUNT(CASE WHEN discount_applied = 'Yes' THEN 1 END) * 100.0
        / COUNT(*)
    AS DECIMAL(5,2)) AS discount_rate
FROM customer_data
GROUP BY item_purchased
ORDER BY discount_rate DESC;

--Q7. Segment customers into New, Returning, and Loyal 
--    based on their total number of previous purchases, and show the count of each segment.
WITH segment_data AS 
(
	SELECT
		customer_id,
		previous_purchases,
		CASE 
			WHEN previous_purchases <= 1 THEN 'New'
			WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
			ELSE 'Loyal'
		END AS customer_segment
	FROM customer_data
) 
SELECT
	customer_segment,
	COUNT(customer_id) as total_customers,
	SUM(previous_purchases) AS total_prev_purchase
FROM segment_data
GROUP BY customer_segment;

--Q8. What are the top 3 most purchased products within each category?

WITH item_count AS
(
	SELECT 
		category,
		item_purchased,
		COUNT(customer_id) AS total_orders,
		ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
FROM customer_data
GROUP BY category,item_purchased
)
	SELECT
		category,
		item_purchased,
		total_orders,
		item_rank
FROM item_count
WHERE item_rank<=3;

--Q9. Are customers who are repeated buyers (more than 5 previous purchases) also likely to subscribe?
SELECT
	subscription_status,
	COUNT(customer_id) AS repeated_buyers
FROM customer_data
WHERE previous_purchases>5
GROUP BY subscription_status


--Q10. What is the revenue contribution of each age group? 
SELECT 
	age_group,
	SUM(purchase_amount) AS revenue_contribution 
FROM customer_data
GROUP BY age_group
ORDER BY revenue_contribution DESC

--11 Average CLV by age group
SELECT age_group,
       AVG(previous_purchases * purchase_amount) AS avg_clv
FROM customer_data
GROUP BY age_group
ORDER BY avg_clv DESC;
